import React from "react";
import { Outlet, NavLink } from "react-router-dom";
import "../styles/admin.css";     // ✅ go up one folder to styles
// import AdminHeader from "./AdminHeader";  // ✅ same folder
// import AdminFooter from "./AdminFooter";  // ✅ same folder
import AdminHeader from "./Header";
import AdminFooter from "./Footer";

export default function AdminLayout() {
  return (
    <>
      <AdminHeader />
      <div className="admin-layout">
        <aside className="admin-sidebar">
          <h2>Admin Panel</h2>
          <nav>
            <NavLink to="/admin/dashboard">Dashboard</NavLink>
            <NavLink to="/admin/teachers">Manage Teachers</NavLink>
            <NavLink to="/admin/notices">Notices</NavLink>
          </nav>
        </aside>

        <main className="admin-content">
          <Outlet />
        </main>
      </div>
      <AdminFooter />
    </>
  );
}
